<?php $photos = $props['photos']; $name = $props['name']; ?>
<div class="companion-gallery" data-media-gallery>
    <?php $first = $photos[0]; ?><a class="gallery-cover" href="<?= e($first['src']) ?>" data-gallery-open="0" data-cursor="zoom"><img data-animal-media src="<?= e($first['src']) ?>" alt="<?= e($first['alt']) ?>" width="900" height="700" fetchpriority="high"><span><?= icon('expand') ?> Ampliar vista</span></a>
    <?php if (count($photos) > 1): ?><div class="gallery-thumbs" aria-label="Vistas de <?= e($name) ?>"><?php foreach ($photos as $index=>$photo): ?><a href="<?= e($photo['src']) ?>" data-gallery-open="<?= $index ?>" aria-label="Ampliar vista <?= $index + 1 ?> de <?= e($name) ?>"><img data-animal-media src="<?= e($photo['src']) ?>" alt="<?= e($photo['alt']) ?>" width="180" height="130" loading="lazy"></a><?php endforeach ?></div><?php endif ?>
    <dialog class="gallery-dialog" data-gallery-dialog aria-label="Galería de <?= e($name) ?>"><div class="gallery-dialog-top"><h2><?= e($name) ?></h2><button type="button" class="gallery-close" data-gallery-close aria-label="Cerrar galería"><?= icon('close') ?></button></div><img data-gallery-image alt=""><div class="gallery-dialog-controls"><button type="button" class="btn btn-outline" data-gallery-previous aria-label="Vista anterior"><?= icon('arrow-left') ?></button><p role="status" data-gallery-count></p><button type="button" class="btn btn-outline" data-gallery-next aria-label="Vista siguiente"><?= icon('arrow-right') ?></button></div></dialog>
</div>
